-- Exact external transport functions, ownership and effective ACLs. Read only.
DO $external_verify$
DECLARE e record;p record;expected name[];actual name[];n integer;external_enabled boolean;catalogue record;schema_actual jsonb;

BEGIN
 external_enabled:=CASE WHEN to_regrole('muse_events') IS NULL THEN false ELSE has_schema_privilege('muse_events','forge_external_agent_api','USAGE') END;
 IF NOT EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=20 AND name='external_agent_transport') THEN RAISE EXCEPTION 'Missing external transport migration20';END IF;
 FOR e IN SELECT * FROM(VALUES
('forge_external_agent._immutable()','0aca9d6f4d2fe2a6abc8a8f4be36c3be2ba21e0638c3085fba21a3085574ad39','owner'),
('forge_external_agent._intent(forge_agent.coding_tasks)','c3431a5f215b89cee8d7b3952ee0976411ab99d48e816b8684f19c00a4bb106f','owner'),
('forge_external_agent._event(forge_external_agent.assignments,text,jsonb)','352c952a22d22183db1dfcda2a208665d669865aa9b956d0d0f66d44bc59c690','owner'),
('forge_external_agent._scope(text,text)',CASE WHEN EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=39) THEN '516bd7bccfcae3a623a92fe0fedb14575b310c10966de89c8f17f0a962f54fe8' ELSE 'daa052a85d3a8e453d1955e03dff2851fe99539095f2cd75c0338f8e9511b856' END,'owner'),
('forge_external_agent._locked(uuid)',CASE WHEN EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=39) THEN '70e2de3a216e4a5a99f70bfaad7b8b2bd89241aa8a3f765dabad90707d78716a' ELSE '9b2ce25433429f750a7bb7e25bb881dc513fea153e7db7abbe236508c115cddc' END,'owner'),
('forge_external_agent._active(uuid,integer,uuid)','4f64a8c58cfd863635db36eb6b6f2528aa33adcc9c399225a7606952936db7bf','owner'),
('forge_external_agent_api.capabilities()',CASE WHEN EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=22) THEN '837b3aaff1f0564222533f3d8d11f3659aa4c91d3a2b95ea6b860bac2376e3a8' ELSE '29f39bbe8c25e743328321b2583a38a8fde4d9152f00b81eae5f5a8a29676e70' END,'external'),
('forge_external_agent_api.advertise(text,text,text)','99f7b450071f3df31cbb787eccdd1b5db1e19ceb63ef9d12c46fb58f3abd26eb','external_writer'),
('forge_external_agent_api.enqueue(text,text,uuid)','4b404350b4e6be45072512d8732b866f2bfaf9f418c0cc5984d17110a86ff0b2','service'),
('forge_external_agent_api.catalogue(text)','c1fd78219edaee347b6b01c4120c772bd562171ba92203156241bc90196a10d6','service'),
('forge_external_agent._housekeep(forge_external_agent.scope_grants,integer)',CASE WHEN EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=39) THEN 'e910dc1d03402e07e83d7c5ebef4e4aff5157b25bf7982ff68e7fae1641a048a' ELSE 'cf30d12f3410e93e3d008b6b448f0b0824141a362e2a0e61e18ad4c2bb5d3992' END,'owner'),
('forge_external_agent_api.reconcile(text)','202bce21b8d500b4173409a997ce886c389c9cbde8ea7a1b6b98038d6a49d89c','service'),
('forge_external_agent_api.claim(text,text)',CASE WHEN EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=22) THEN '71bf496f1093265d61265fbc9171cc1e9f3f00c3f383508d8cba894aca9b8893' ELSE '9c028a7060095d201506e623e536f39d45e28432d29992485c5e75a2dc81b8b1' END,'external_writer'),
('forge_external_agent_api.renew(uuid,integer,uuid)','1a8f4d3e147ec4788069a7a326a30eaf5d8466b222d67b24584f9e3dbd6164cd','external_writer'),
('forge_external_agent_api.progress(uuid,integer,uuid,text)','81b76cbc125c3547613652c7d30aecad3882aa552ebb5c2d03569d8fb0938f60','external_writer'),
('forge_external_agent_api.finish(uuid,integer,uuid,text,text)',CASE WHEN EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=39) THEN '2815981ff0590cc66a72894d90a44e4f6745c938141decb501677d9d954aa096' ELSE 'f1a6021104181e3ad54a100552aca86da51ace1df6caece3e3c66ed66916a8b7' END,'external_writer'),
('forge_external_agent_api.release(uuid,integer,uuid)','d451c3028a608ebe4d207a2ede38003fe8cafc60f3f9f07195e0616e9fc799d6','external_writer'),
('forge_external_agent._artifact(uuid)','13730c4876efc64c5eaccc7d5d53c53c4743713c824961402a7b007a97fea72c','owner'),
('forge_external_agent_api.artifact(uuid)','d5f044d5aa5cfe4f9e62c9fa3336eb1d5b3f4a6ddc9e6ae5ac034f1af04880e4','external'),
('forge_external_agent_api.artifact_by_task(text,text,uuid)','9287ef9f7ffa18a1e99252dbdfb175d0e638ec8774af40e4210bb3721e90f4db','service')
 ) AS specs(signature,digest,access) LOOP
 SELECT * INTO p FROM pg_proc WHERE oid=to_regprocedure(e.signature);
 IF NOT FOUND OR p.proowner<>'forge_agent_owner'::regrole OR NOT p.prosecdef OR p.proconfig IS DISTINCT FROM ARRAY['search_path=pg_catalog, pg_temp'] OR p.provolatile<>'v'
 OR p.prokind<>'f' OR p.proretset OR p.proisstrict OR p.proleakproof OR p.proparallel<>'u' OR p.provariadic<>0 OR p.pronargdefaults<>0
 OR p.prolang<>(SELECT oid FROM pg_language WHERE lanname=CASE WHEN e.signature IN('forge_external_agent._intent(forge_agent.coding_tasks)','forge_external_agent._artifact(uuid)') THEN 'sql' ELSE 'plpgsql' END)
 OR p.prorettype<>(CASE WHEN e.signature='forge_external_agent._immutable()' THEN 'trigger' WHEN e.signature='forge_external_agent._event(forge_external_agent.assignments,text,jsonb)' THEN 'void' WHEN e.signature='forge_external_agent._scope(text,text)' THEN 'forge_external_agent.scope_grants' WHEN e.signature IN('forge_external_agent._locked(uuid)','forge_external_agent._active(uuid,integer,uuid)') THEN 'forge_external_agent.assignments' WHEN e.signature='forge_external_agent._housekeep(forge_external_agent.scope_grants,integer)' THEN 'integer' WHEN e.signature='forge_external_agent_api.enqueue(text,text,uuid)' THEN 'uuid' ELSE 'jsonb' END)::regtype
 OR encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')<>e.digest THEN RAISE EXCEPTION 'External function definition drift: %',e.signature;END IF;
 expected:=ARRAY['forge_agent_owner']::name[];
 IF e.access='service' THEN expected:=expected||'forge_agent'::name;END IF;
 IF e.access='external' AND external_enabled THEN expected:=expected||'muse_events'::name;END IF;
 IF e.access='external_writer' THEN
  IF NOT EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=40) AND external_enabled THEN expected:=expected||'muse_events'::name;END IF;
  IF EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=39) THEN expected:=expected||'muse_proxy_writer'::name;END IF;
 END IF;
 SELECT array_agg(r.rolname ORDER BY r.rolname) INTO actual FROM aclexplode(p.proacl) a JOIN pg_roles r ON r.oid=a.grantee WHERE a.privilege_type='EXECUTE' AND NOT a.is_grantable;
 SELECT array_agg(x ORDER BY x) INTO expected FROM unnest(expected) x;
 IF actual IS DISTINCT FROM expected OR EXISTS(SELECT FROM aclexplode(p.proacl) a WHERE a.grantee=0 OR a.privilege_type<>'EXECUTE' OR a.is_grantable OR a.grantor<>'forge_agent_owner'::regrole) THEN RAISE EXCEPTION 'External function ACL drift: %',e.signature;END IF;
 END LOOP;
 SELECT count(*) INTO n FROM pg_proc WHERE pronamespace IN('forge_external_agent'::regnamespace,'forge_external_agent_api'::regnamespace);
 IF n<>(20+CASE WHEN EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=21) THEN 1 ELSE 0 END) THEN RAISE EXCEPTION 'Unexpected external functions';END IF;
 FOR e IN SELECT * FROM(VALUES('forge_external_agent',CASE WHEN EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=39 AND name='pg_proxy_preparation') THEN ARRAY['forge_agent_owner','forge_agent','muse_proxy_writer']::name[] ELSE ARRAY['forge_agent_owner']::name[] END),('forge_external_agent_api',CASE WHEN NOT external_enabled THEN CASE WHEN EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=39) THEN ARRAY['forge_agent_owner','forge_agent','muse_proxy_writer']::name[] ELSE ARRAY['forge_agent_owner','forge_agent']::name[] END WHEN EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=39) THEN ARRAY['forge_agent_owner','forge_agent','muse_events','muse_proxy_writer']::name[] ELSE ARRAY['forge_agent_owner','forge_agent','muse_events']::name[] END)) AS schemas(name,roles) LOOP
 SELECT array_agg(r.rolname ORDER BY r.rolname) INTO actual FROM pg_namespace n,LATERAL aclexplode(n.nspacl) a JOIN pg_roles r ON r.oid=a.grantee WHERE n.nspname=e.name AND a.privilege_type='USAGE' AND NOT a.is_grantable;
 SELECT array_agg(x ORDER BY x) INTO expected FROM unnest(e.roles) x;
 IF actual IS DISTINCT FROM expected OR EXISTS(SELECT FROM pg_namespace n,LATERAL aclexplode(n.nspacl) a WHERE n.nspname=e.name AND (a.grantee=0 OR a.grantor<>'forge_agent_owner'::regrole OR (a.grantee<>'forge_agent_owner'::regrole AND(a.privilege_type<>'USAGE' OR a.is_grantable)))) THEN RAISE EXCEPTION 'External schema ACL drift: %',e.name;END IF;
 END LOOP;
 IF EXISTS(SELECT FROM pg_namespace WHERE nspname IN('forge_external_agent','forge_external_agent_api') AND nspowner<>'forge_agent_owner'::regrole)
 OR EXISTS(SELECT FROM pg_class c WHERE c.relnamespace='forge_external_agent'::regnamespace AND c.relowner<>'forge_agent_owner'::regrole)
 OR EXISTS(SELECT FROM pg_class c,LATERAL aclexplode(c.relacl) a WHERE c.relnamespace='forge_external_agent'::regnamespace AND a.grantee<>'forge_agent_owner'::regrole AND NOT(a.grantee IN('forge_agent'::regrole,'muse_proxy_writer'::regrole) AND a.privilege_type='SELECT' AND NOT a.is_grantable))
 OR EXISTS(SELECT FROM pg_attribute c JOIN pg_class t ON t.oid=c.attrelid,LATERAL aclexplode(c.attacl) a WHERE t.relnamespace='forge_external_agent'::regnamespace) THEN RAISE EXCEPTION 'External storage ownership or ACL drift';END IF;
 FOR catalogue IN SELECT * FROM(VALUES
('artifacts',$table${"acl":["forge_agent_owner=arwdDxt/forge_agent_owner"],"columns":[["assignment_id","uuid",true,null],["provider","text",true,"'muse-db'::text"],["sha256","text",true,null],["content","text",true,null],["summary","text",true,null],["submitted_at","timestamp with time zone",true,"clock_timestamp()"],["principal","name",true,null],["generation","integer",true,null],["recipe_digest","text",true,null]],"constraints":[["artifacts_assignment_id_fkey","f","FOREIGN KEY (assignment_id) REFERENCES forge_external_agent.assignments(assignment_id)",true,false,false],["artifacts_content_check","c","CHECK (((octet_length(content) >= 1) AND (octet_length(content) <= 262144)))",true,false,false],["artifacts_generation_check","c","CHECK (((generation >= 1) AND (generation <= 3)))",true,false,false],["artifacts_pkey","p","PRIMARY KEY (assignment_id)",true,false,false],["artifacts_provider_check","c","CHECK ((provider = 'muse-db'::text))",true,false,false],["artifacts_sha256_check","c","CHECK ((sha256 ~ '^[0-9a-f]{64}$'::text))",true,false,false],["artifacts_summary_check","c","CHECK (((octet_length(summary) >= 1) AND (octet_length(summary) <= 4096)))",true,false,false]],"force_row_security":false,"indexes":[["artifacts_pkey","CREATE UNIQUE INDEX artifacts_pkey ON forge_external_agent.artifacts USING btree (assignment_id)",true,true]],"kind":"r","persistence":"p","row_security":false,"triggers":[["external_artifact_immutable","CREATE TRIGGER external_artifact_immutable BEFORE DELETE OR UPDATE ON forge_external_agent.artifacts FOR EACH ROW EXECUTE FUNCTION forge_external_agent._immutable()","O"]]}$table$::jsonb),('assignments',$table${"acl":["forge_agent_owner=arwdDxt/forge_agent_owner"],"columns":[["assignment_id","uuid",true,"gen_random_uuid()"],["external_role","name",true,null],["owner_id","text",true,null],["project_alias","text",true,null],["profile_alias","text",true,null],["task_id","uuid",true,null],["intent","jsonb",true,null],["intent_digest","text",true,null],["status","text",true,"'queued'::text"],["task_revision","bigint",true,null],["generation","integer",true,"0"],["lease_token","uuid",false,null],["lease_until","timestamp with time zone",false,null],["deadline_at","timestamp with time zone",true,"(clock_timestamp() + '24:00:00'::interval)"],["finish_token","uuid",false,null],["finish_intent","text",false,null],["receipt","jsonb",false,null],["created_at","timestamp with time zone",true,"clock_timestamp()"],["updated_at","timestamp with time zone",true,"clock_timestamp()"]],"constraints":[["assignments_check","c","CHECK ((((status = 'leased'::text) AND (lease_token IS NOT NULL) AND (lease_until IS NOT NULL)) OR ((status <> 'leased'::text) AND (lease_token IS NULL) AND (lease_until IS NULL))))",true,false,false],["assignments_check1","c","CHECK ((((status = 'submitted'::text) AND (finish_token IS NOT NULL) AND (finish_intent IS NOT NULL) AND (receipt IS NOT NULL)) OR ((status <> 'submitted'::text) AND (finish_token IS NULL) AND (finish_intent IS NULL) AND (receipt IS NULL))))",true,false,false],["assignments_external_role_owner_id_project_alias_profile_a_fkey","f","FOREIGN KEY (external_role, owner_id, project_alias, profile_alias) REFERENCES forge_external_agent.scope_grants(external_role, owner_id, project_alias, profile_alias)",true,false,false],["assignments_generation_check","c","CHECK (((generation >= 0) AND (generation <= 3)))",true,false,false],["assignments_intent_digest_check","c","CHECK ((intent_digest ~ '^[0-9a-f]{64}$'::text))",true,false,false],["assignments_owner_id_project_alias_task_id_fkey","f","FOREIGN KEY (owner_id, project_alias, task_id) REFERENCES forge_agent.coding_tasks(owner_id, project_alias, id)",true,false,false],["assignments_owner_id_project_alias_task_id_key","u","UNIQUE (owner_id, project_alias, task_id)",true,false,false],["assignments_pkey","p","PRIMARY KEY (assignment_id)",true,false,false],["assignments_status_check","c","CHECK ((status = ANY (ARRAY['queued'::text, 'leased'::text, 'submitted'::text, 'failed'::text, 'cancelled'::text])))",true,false,false],["assignments_task_revision_check","c","CHECK (((task_revision >= 1) AND (task_revision <= '9007199254740991'::bigint)))",true,false,false]],"force_row_security":false,"indexes":[["assignments_owner_id_project_alias_task_id_key","CREATE UNIQUE INDEX assignments_owner_id_project_alias_task_id_key ON forge_external_agent.assignments USING btree (owner_id, project_alias, task_id)",true,true],["assignments_pkey","CREATE UNIQUE INDEX assignments_pkey ON forge_external_agent.assignments USING btree (assignment_id)",true,true],["external_assignments_pending","CREATE INDEX external_assignments_pending ON forge_external_agent.assignments USING btree (external_role, project_alias, profile_alias, status, created_at)",true,true]],"kind":"r","persistence":"p","row_security":false,"triggers":[["external_assignment_binding","CREATE TRIGGER external_assignment_binding BEFORE UPDATE ON forge_external_agent.assignments FOR EACH ROW EXECUTE FUNCTION forge_external_agent._immutable()","O"]]}$table$::jsonb),('readiness',$table${"acl":["forge_agent_owner=arwdDxt/forge_agent_owner"],"columns":[["external_role","name",true,null],["owner_id","text",true,null],["project_alias","text",true,null],["profile_alias","text",true,null],["runner_id","text",true,null],["observed_at","timestamp with time zone",true,null]],"constraints":[["readiness_external_role_owner_id_project_alias_profile_ali_fkey","f","FOREIGN KEY (external_role, owner_id, project_alias, profile_alias) REFERENCES forge_external_agent.scope_grants(external_role, owner_id, project_alias, profile_alias)",true,false,false],["readiness_pkey","p","PRIMARY KEY (external_role, owner_id, project_alias, profile_alias)",true,false,false],["readiness_runner_id_check","c","CHECK ((runner_id ~ '^[A-Za-z0-9_.-]{1,64}$'::text))",true,false,false]],"force_row_security":false,"indexes":[["readiness_pkey","CREATE UNIQUE INDEX readiness_pkey ON forge_external_agent.readiness USING btree (external_role, owner_id, project_alias, profile_alias)",true,true]],"kind":"r","persistence":"p","row_security":false,"triggers":[]}$table$::jsonb),('scope_grants',$table${"acl":["forge_agent_owner=arwdDxt/forge_agent_owner"],"columns":[["external_role","name",true,null],["service_role","name",true,"'forge_agent'::name"],["owner_id","text",true,null],["project_alias","text",true,null],["profile_alias","text",true,null],["enabled","boolean",true,"false"]],"constraints":[["scope_grants_owner_id_check","c","CHECK ((((octet_length(owner_id) >= 1) AND (octet_length(owner_id) <= 128)) AND (btrim(owner_id) <> ''::text)))",true,false,false],["scope_grants_pkey","p","PRIMARY KEY (external_role, owner_id, project_alias, profile_alias)",true,false,false],["scope_grants_profile_alias_check","c","CHECK ((profile_alias ~ '^[A-Za-z0-9_.-]{1,64}$'::text))",true,false,false],["scope_grants_project_alias_check","c","CHECK ((project_alias ~ '^[A-Za-z0-9_.-]{1,64}$'::text))",true,false,false]],"force_row_security":false,"indexes":[["scope_grants_pkey","CREATE UNIQUE INDEX scope_grants_pkey ON forge_external_agent.scope_grants USING btree (external_role, owner_id, project_alias, profile_alias)",true,true]],"kind":"r","persistence":"p","row_security":false,"triggers":[]}$table$::jsonb)
 ) AS expected(name,data) LOOP
 SELECT jsonb_build_object('kind',c.relkind,'persistence',c.relpersistence,'row_security',c.relrowsecurity,'force_row_security',c.relforcerowsecurity,
 'columns',(SELECT jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT coalesce(jsonb_agg(jsonb_build_array(x.conname,x.contype,pg_get_constraintdef(x.oid),x.convalidated,x.condeferrable,x.condeferred) ORDER BY x.conname),'[]') FROM pg_constraint x WHERE x.conrelid=c.oid),
 'indexes',(SELECT coalesce(jsonb_agg(jsonb_build_array(i.relname,pg_get_indexdef(i.oid),x.indisvalid,x.indisready) ORDER BY i.relname),'[]') FROM pg_index x JOIN pg_class i ON i.oid=x.indexrelid WHERE x.indrelid=c.oid),'acl',to_jsonb(c.relacl),
 'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_array(t.tgname,pg_get_triggerdef(t.oid),t.tgenabled) ORDER BY t.tgname),'[]') FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal)) INTO schema_actual
 FROM pg_class c WHERE c.relnamespace='forge_external_agent'::regnamespace AND c.relname=catalogue.name;
 -- M39 grants the proxy read surface (forge_agent and muse_proxy_writer
 -- SELECT) on every external table; the pinned catalog expects exactly
 -- those entries from here on.
 IF EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=39 AND name='pg_proxy_preparation') THEN
  catalogue.data:=jsonb_set(catalogue.data,'{acl}','["forge_agent_owner=arwdDxt/forge_agent_owner","forge_agent=r/forge_agent_owner","muse_proxy_writer=r/forge_agent_owner"]'::jsonb);
 END IF;
 IF schema_actual IS DISTINCT FROM catalogue.data THEN RAISE EXCEPTION 'External table catalog drift: %',catalogue.name;END IF;
 END LOOP;
 IF(SELECT count(*) FROM pg_class WHERE relnamespace='forge_external_agent'::regnamespace AND relkind IN('r','p','v','m','f','S'))<>4 THEN RAISE EXCEPTION 'Unexpected external relations';END IF;
END;
$external_verify$;
